<script setup lang="ts">import {computed,ref} from 'vue';import {useRoute} from 'vue-router';import {useResearchData} from '../hooks/useResearch';import RunSummary from '../components/RunSummary.vue';import SurvivalPlot from '../components/SurvivalPlot.vue';import RiskTable from '../components/RiskTable.vue';import StatusBadge from '../components/common/StatusBadge.vue';import Notice from '../components/common/Notice.vue';import DataTable from '../components/common/DataTable.vue';import {number,probability} from '../utils/format';const s=useResearchData(true),route=useRoute(),selected=ref(Number(route.query.run)||0);const run=computed(()=>s.runs.find(r=>r.id===selected.value)||s.runs[0]);</script><template><div class="page results-page"><div class="page-title"><div><p class="eyebrow">SURVIVAL EVIDENCE / 04</p><h1>耐久结果<span>同时阅读曲线、在险人数与不确定性。</span></h1></div><RouterLink class="outline" :to="'/notes'+(run?'?run='+run.id:'')">记录维护建议 →</RouterLink></div><Notice :message="s.error" @retry="s.refresh"/><div class="run-picker"><label>研究档案<select aria-label="研究档案" :value="run?.id||''" @change="selected=Number(($event.target as HTMLSelectElement).value)"><option v-for="r in s.runs" :key="r.id" :value="r.id">#{{r.id}} / {{r.name}} / {{r.status}}</option></select></label><StatusBadge v-if="run" :status="run.status"/></div><template v-if="run?.status==='completed'"><RunSummary :run="run"/><SurvivalPlot :result="run.result"/><RiskTable :result="run.result"/><div class="comparison-note"><span>LOG-RANK</span><p>{{run.result.interpretation}}</p><b>χ² {{number(run.result.logrank.chi_square,4)}} / p {{probability(run.result.logrank.p_value)}}</b></div><p class="caption">{{run.result.assumptions}}</p><div class="section-heading"><h2>并列事件与风险集明细</h2><span>前12个事件时点</span></div><DataTable :head="['时间 / h','A在险','B在险','A事件','B事件','A期望事件','方差项']"><tr v-for="p in run.result.logrank.event_table.slice(0,12)" :key="p.time"><td>{{p.time}}</td><td>{{p.risk_a}}</td><td>{{p.risk_b}}</td><td>{{p.events_a}}</td><td>{{p.events_b}}</td><td>{{number(p.expected_a,4)}}</td><td>{{number(p.variance,4)}}</td></tr></DataTable><p class="fingerprint">输入SHA256 {{run.result.input_hash}}</p></template><div v-else-if="run" class="pending"><h2>{{run.status==='failed'?'研究未能完成':'后台正在整理耐久曲线'}}</h2><p>{{run.error||'独立worker执行KM、Greenwood区间与log-rank，本页每2秒更新。'}}</p></div><p v-else class="empty">尚无研究，请先选择两批工艺创建比较。</p></div></template>
